  "Team Mega"
  |> spring_cleaning.remove_team_prefix
  |> should.equal("Mega")
}

pub fn remove_team_prefix_team_sync_test() {
  "Team Sync"
  |> spring_cleaning.remove_team_prefix
  |> should.equal("Sync")
}

